fn running_totals(values: &[i32]) -> Vec<i32> {
    let mut total = 0;
    let mut out = Vec::with_capacity(values.len());
    for v in values {
        total += v;
        out.push(total);
    }
    out
}

fn remove_negatives(values: &mut Vec<i32>) {
    values.retain(|&v| v >= 0);
}

fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend(&a[i..]);
    out.extend(&b[j..]);
    out
}

fn top_n(values: &[i32], n: usize) -> Vec<i32> {
    let mut sorted = values.to_vec();
    sorted.sort();
    let mut out = Vec::new();
    while out.len() < n {
        match sorted.pop() {
            Some(v) => out.push(v),
            None => break,
        }
    }
    out
}

fn unique_in_order(values: &[i32]) -> Vec<i32> {
    let mut out = Vec::new();
    for &v in values {
        if !out.contains(&v) {
            out.push(v);
        }
    }
    out
}

unitTests:
test("running totals", || {
    check_eq(running_totals(&[1, 2, 3]), vec![1, 3, 6]);
    check_eq(running_totals(&[5, -5, 5]), vec![5, 0, 5]);
    check_eq(running_totals(&[]), Vec::<i32>::new());
});

test("removing negatives in place", || {
    let mut v = vec![-1, 4, -2, -3, 7, 0, -9];
    remove_negatives(&mut v);
    check_eq(v, vec![4, 7, 0]);
});

test("merging", || {
    check_eq(merge_sorted(&[1, 4, 9], &[2, 3, 10, 11]), vec![1, 2, 3, 4, 9, 10, 11]);
    check_eq(merge_sorted(&[], &[5]), vec![5]);
    check_eq(merge_sorted(&[2, 2], &[2]), vec![2, 2, 2]);
});

test("top n", || {
    let data = [5, 1, 9, 3, 9, 7];
    check_eq(top_n(&data, 3), vec![9, 9, 7]);
    check_eq(top_n(&data, 10).len(), 6);
    check_eq(top_n(&data, 0), Vec::<i32>::new());
    check_eq(data, [5, 1, 9, 3, 9, 7]);
});

test("unique in order", || {
    check_eq(unique_in_order(&[3, 1, 3, 2, 1]), vec![3, 1, 2]);
    check_eq(unique_in_order(&[]), Vec::<i32>::new());
});

